// Sıcaklıkla fan: NTC sıcaklığı ölçer, röle fanı histerezisle açıp kapatır.
const int NTC_PIN = A0;      // NTC modülü OUT
const int ROLE_PIN = 7;      // röle modülü IN
const int LED_PIN = 8;       // durum LED'i: fan çalışırken yanar

const float ACMA_C = 30.0;   // bunun üstünde fan açılır
const float KAPAMA_C = 27.0; // bunun altında fan kapanır
const float BETA = 3950;     // NTC'nin B değeri (modülün belgesinde yazar)
const unsigned long OLCUM_MS = 1000;

// Çoğu röle modülü LOW ile çeker. Seninki HIGH ile çekiyorsa bu iki satırı değiştir.
const int ROLE_ACIK = LOW;
const int ROLE_KAPALI = HIGH;

bool fanAcik = false;

// 10 okumanın ortalamasından sıcaklığı (°C) hesaplar.
float sicaklikOku() {
  long toplam = 0;
  for (int i = 0; i < 10; i++) {
    toplam += analogRead(NTC_PIN);
    delay(5);
  }
  float deger = toplam / 10.0;
  if (deger < 1) deger = 1;          // sıfıra bölmeyi önle
  if (deger > 1022) deger = 1022;
  return 1 / (log(1 / (1023.0 / deger - 1)) / BETA + 1.0 / 298.15) - 273.15;
}

void fanAyarla(bool ac) {
  fanAcik = ac;
  digitalWrite(ROLE_PIN, ac ? ROLE_ACIK : ROLE_KAPALI);
  digitalWrite(LED_PIN, ac ? HIGH : LOW);
}

void setup() {
  Serial.begin(9600);
  pinMode(ROLE_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  fanAyarla(false);
  Serial.println("Hazir. Fan kapali.");
}

void loop() {
  float c = sicaklikOku();

  // Histerezis: iki eşik arasında durum değişmez; fan sık sık açılıp kapanmaz.
  if (!fanAcik && c > ACMA_C) fanAyarla(true);
  else if (fanAcik && c < KAPAMA_C) fanAyarla(false);

  Serial.print("Sicaklik: ");
  Serial.print(c, 1);
  Serial.print(" C  Fan: ");
  Serial.println(fanAcik ? "ACIK" : "KAPALI");
  delay(OLCUM_MS);
}
